for dr,dc,v in shape: put(out2,3+dr,5+dc,v)
for r,c in targets2:
    for dr,dc,v in shape: put(out2,r+dr,c+dc,v)
res2=mod.transform(in2)
print('demo2 exact:',res2==out2)
# Report any mismatches for diagnosing the hypothesis.
