print('demo3 exact:',mod.transform(in3)==out3)
in4=blank(15,15,4)
shape4=[(0,0,7),(0,-2,8),(0,-1,8),(0,1,0),(0,2,7),(1,-1,0),(1,0,7),(1,1,7)]
# source bbox rows2-3 cols1-4; anchor is (2,2): actual offsets from anchor
