put(in4,2,0,8)
targets4=[(9,4),(9,11),(13,6)]
for r,c in targets4: put(in4,r,c,5)
print('demo4 component listing',[(r,c,v) for r,row in enumerate(in4) for c,v in enumerate(row) if v!=4])

shape4=[(0,-2,8),(0,-1,8),(0,0,9),(0,1,0),(0,2,7),(1,-1,0),(1,0,7),(1,1,7)]
in4=blank(15,15,4)
for dr,dc,v in shape4: put(in4,2+dr,2+dc,v)
targets4=[(9,4),(9,11),(13,6)]
for r,c in targets4: put(in4,r,c,5)
out4=blank(15,15,4)
for dr,dc,v in shape4: put(out4,2+dr,2+dc,v)
for r,c in targets4:
    for dr,dc,v in shape4: put(out4,r+dr,c+dc,v)
print('demo4 exact:',mod.transform(in4)==out4)
print('demo4 transform unique vals at output',[(r,c,mod.transform(in4)[r][c]) for r,c in [(8,4),(9,4),(10,4),(12,6),(13,6),(14,6)]])

